    return out"},{"nl":"Erase the unique center pixel when it is color 1, while preserving the rest of the picture.","code":"def transform(grid):
    out=[r[:] for r in grid]
    if len(out)==5 and all(len(r)==5 for r in out) and out[2][2]==1: out[2][2]=0
    return out"},{"nl":"Clear the middle cell of a square grid; for nonsquare grids use identity.","code":"def transform(grid):
    out=[r[:] for r in grid]
    if out and len(out)==len(out[0]) and len(out)%2==1: out[len(out)//2][len(out)//2]=0
    return out"},{"nl":"Change the central non-background object to background and also recolor any other color-1 cells to zero.","code":"def transform(grid):
    return [[0 if x==1 else x for x in r] for r in grid]"},{"nl":"Clear the center cell and its immediate right neighbor in any 5x5 grid.","code":"def transform(grid):
    out=[r[:] for r in grid]
    if len(out)==5 and all(len(r)==5 for r in out): out[2][2]=0; out[2][3]=0
    return out"},{"nl":"Clear the center cell and the top-left corner of a 5x5 grid.","code":"def transform(grid):
    out=[r[:] for r in grid]
